+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+
+/** Immutable backend filter shared by page and count queries. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    public List<String> terms() {
+        return Arrays.stream(fold(name).split("(?U)\\s+"))
+                .filter(term -> !term.isEmpty()).toList();
+    }
+
+    static String fold(String value) {
+        return Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}+", "").toLowerCase(Locale.ROOT);
+    }
+}
